// Today = 2026-11-09 in Europe/Warsaw (CET, UTC+1)
const START = Date.UTC(2026, 10, 8, 23, 0, 0) / 1000;
const END = START + 86400;
const seen = {};
const perLang = {};
const rows = [];
const created = [];
let total = 0;
for (const it of $input.all()) {
  for (const k of (it.json.keys || [])) {
    if (seen[k.key_id]) { continue; }
    seen[k.key_id] = 1;
    total++;
    const nm = k.key_name;
    const name = (nm && typeof nm === 'object') ? (nm.web || nm.other || nm.ios || nm.android || JSON.stringify(nm)) : nm;
    const c = k.created_at_timestamp || 0;
    const createdToday = c >= START && c < END;
    if (createdToday) { created.push(name); }
    for (const tr of (k.translations || [])) {
      const m = tr.modified_at_timestamp || 0;
      if (!(m >= START && m < END)) { continue; }
      const iso = (tr.language_iso || '').toLowerCase();
      perLang[iso] = (perLang[iso] || 0) + 1;
      if (iso !== 'en' && iso.indexOf('en_') !== 0 && iso.indexOf('en-') !== 0) { continue; }
      let txt = tr.translation;
      if (txt && typeof txt === 'object') { txt = JSON.stringify(txt); }
      rows.push({ key_id: k.key_id, name: name, iso: iso, created_today: createdToday, modified_at: tr.modified_at, by: tr.modified_by_email, text: String(txt || '').slice(0, 300), tags: k.tags || [] });
    }
  }
}
return [{ json: { total_keys_scanned: total, pages: $input.all().length, modified_today_per_lang: perLang, keys_created_today: created, matched_count: rows.length, matched: rows } }];
